        description: Candidate full name passed through from stg_greenhouse__candidate
      - name: current_company
        data_type: VARCHAR
        description: Candidate current company passed through from stg_greenhouse__candidate
      - name: current_title
        data_type: VARCHAR
        description: Candidate current title passed through from stg_greenhouse__candidate
      - name: coordinator_user_id
        data_type: BIGINT
        description: Greenhouse user_id of the candidate's coordinator passed through from stg_greenhouse__candidate
      - name: recruiter_user_id
        data_type: BIGINT
        description: Greenhouse user_id of the candidate's recruiter passed through from stg_greenhouse__candidate
      - name: created_at
        data_type: TIMESTAMP
        description: Timestamp when the candidate record was created passed through from stg_greenhouse__candidate
      - name: last_updated_at
